// src/analyzers/broad-paths.ts
import { normalize as normalize2 } from "path";
function buildBroadPaths(home) {
  return [
    { path: "/", reason: "covers the entire filesystem" },
    { path: home, reason: "covers the entire home directory" },
    { path: "/tmp", reason: "shared by all local users" },
    { path: "/var/tmp", reason: "shared by all local users" },
    { path: "/etc", reason: "system configuration directory" }
  ];
}
function expandHome2(p, home) {
  if (p === "~") return home;
  if (p.startsWith("~/")) return `${home}/${p.slice(2)}`;
  return p;
}
function isBroadPath(rawPath, broadPaths, home) {
  const normalized = normalize2(expandHome2(rawPath, home));
  const trimmed = normalized.length > 1 && normalized.endsWith("/") ? normalized.slice(0, -1) : normalized;
  return broadPaths.find((b) => trimmed === b.path);
}

